import { SLOTS, type SlotId, slotUrl } from "./slots";

export interface ArtEntry {
  readonly slot: SlotId;
  /** Public URL of the runtime WebP. */
  readonly file: string;
  readonly width: number;
  readonly height: number;
}

// art:begin generated by task 06, do not edit by hand
export const ART_ENTRIES: readonly ArtEntry[] = [];
// art:end

/** Slots that have a runtime file in `public/art/`; rejected and missing slots stay out. */
export const ART_MANIFEST: readonly SlotId[] = ART_ENTRIES.map((entry) => entry.slot);

export function hasArt(slot: SlotId, manifest: readonly SlotId[] = ART_MANIFEST): boolean {
  return manifest.includes(slot);
}

export function artUrls(manifest: readonly SlotId[] = ART_MANIFEST): string[] {
  return SLOTS.filter((slot) => slot.inBundle && manifest.includes(slot.id)).map((slot) =>
    slotUrl(slot.id),
  );
}
